import {notificationStatusRows} from './notification-status-27ca4e179461.mjs';
import * as D from './domain-27ca4e179461.mjs';
import {enablePhone,stopPhone,correctPhoneSpan,requestPhoneHistory,undoPhoneRebuild} from './phone-domain-27ca4e179461.mjs';
import {renderPhoneCard} from './phone-view-27ca4e179461.mjs';
export function nativePhoneStatus(){try{return globalThis.NGNLNative?.phoneStatus?{available:true,...JSON.parse(globalThis.NGNLNative.phoneStatus())}:{available:false};}catch{return {available:false,error:'系统能力状态暂时无法读取'};}}
export function phoneCard(state,helpers,compact=false){return renderPhoneCard(state,helpers,compact,nativePhoneStatus());}
export function phoneSettings(state,ui,h){const st=ui.nativeStatus??{available:false},opts=state.settings.phone??{},e=h.e;return `<section class="card" data-native-settings><h2>应用外计时与手机识别</h2><button type="button" class="text-button" data-action="notification-privacy">通知隐私与预览</button><button type="button" class="text-button" data-action="phone-details">查看手机统计与更正 ›</button>${st.available?`<dl class="info-list"><div><dt>使用情况访问</dt><dd>${st.usageAllowed?'已授权':'未授权'}</dd></div>${notificationStatusRows(st,opts.privacy??'activity').map(([label,value])=>`<div><dt>${e(label)}</dt><dd>${e(value)}</dd></div>`).join('')}<div><dt>后台状态</dt><dd>${st.running?'服务正在运行':opts.enabled?'已保存设置，后台未运行':'未启用'}</dd></div></dl>${st.error?`<p class="form-error">${e(st.error)}</p>`:''}<button type="button" class="secondary" data-action="timer-channel-settings">打开计时通知与锁屏设置</button><div class="settings-actions"><button type="button" class="secondary" data-action="enable-phone">${opts.enabled?'检查并重新启用手机记录':'启用手机使用记录'}</button>${opts.enabled?'<button type="button" class="text-button" data-action="disable-phone">关闭手机使用记录</button>':''}<button type="button" class="secondary" data-action="phone-app-rules">选择专注时切换的App（${opts.interruptPackages?.length??0}）</button><button type="button" class="secondary" data-action="enable-notifications">${opts.notifications?'检查计时通知':'启用应用外计时通知'}</button>${opts.notifications?'<button type="button" class="text-button" data-action="disable-notifications">关闭计时通知</button>':''}</div>${st.promotedAvailable?`<button type="button" class="text-button" data-action="toggle-live-updates">请求系统醒目展示：${opts.liveUpdates?'已开启':'关闭'}</button>`:''}<p class="quiet-note">手机采集需要系统运行通知。只读取App名称、事件与时间，不读取聊天、输入或屏幕内容。可随时关闭；撤销权限会暂停自动结算。普通通知可展开并操作，OriginOS原子通知另需vivo上架与准入开通，本版本未获该资格；系统实际显示形态以手机为准。</p>`:'<p>网页支持手动计时，可回看备份中的手机记录；按App采集、锁屏自动切换和常驻计时通知需要安卓应用。</p>'}</section>`;}
export function createPhoneControls({getState,save,refresh,openModal,closeModal,toast,e,getNeedsRecovery,recoveryDialog}){
 const bridge=()=>globalThis.NGNLNative;
 const requireNative=()=>{if(!nativePhoneStatus().available)throw new Error('请在安卓应用内设置手机能力');};
 const settings=s=>{s.settings.phone??={enabled:false,interruptPackages:[],notifications:false,liveUpdates:false};return s.settings.phone;};
 function enable(){requireNative();if(getNeedsRecovery()){recoveryDialog();return;}const st=nativePhoneStatus();openModal('由你启用手机使用记录',`<p>只在本机保存App名称和使用时段，不读取聊天、屏幕或输入。系统前台服务会显示运行通知，可在此关闭。</p><p>先授权，再点击下方启用。会尝试补齐系统仍保留的当天时段；回补只影响手机使用，不改主活动与成长。</p><div class="inline-actions"><button type="button" class="secondary" data-action="request-usage">${st.usageAllowed?'查看使用情况权限':'打开使用情况访问设置'}</button><button type="button" class="secondary" data-action="request-notifications">${st.notificationsAllowed?'查看通知权限':'允许通知'}</button></div><p>普通活动保留主计时，并行记录手机使用。专注活动只对你明确选中的App切换到“手机使用”，离开该App或锁屏后恢复原活动。启用会新增这一项活动；不推断具体用途，也不额外加成长分。</p><label class="check"><input type="checkbox" required>我了解记录范围，愿意启用本机采集</label>`,{submit:'启用本机记录',onSubmit:async()=>{const current=nativePhoneStatus();if(!current.usageAllowed||!current.notificationsAllowed)throw new Error('还缺少系统授权；请先完成使用情况访问与通知授权');await save(s=>enablePhone(s));const error=bridge().enableRuntime(true,true);if(error){await save(s=>stopPhone(s));throw new Error(error);}closeModal();toast('已启动手机记录，后台实际状态请在本页核对');await refresh();}});}
 function appRules(){requireNative();const state=getState(),apps=JSON.parse(bridge().selectableApps()),selected=state.settings.phone?.interruptPackages??[];for(const id of selected)if(!apps.some(a=>a.id===id))apps.push({id,name:id});apps.sort((a,b)=>a.name.localeCompare(b.name,'zh'));openModal('专注时，哪些App会切换主活动',`<p>只对选中的App切换。查资料或学习需要的App可以不选；未选App仍只作为并行手机记录。活动本身须设置为专注模式。</p><div class="checkbox-list phone-app-list">${apps.map(a=>`<label><input type="checkbox" name="packages" value="${e(a.id)}" ${selected.includes(a.id)?'checked':''}>${e(a.name)}<small>${e(a.id)}</small></label>`).join('')}</div>`,{onSubmit:async f=>{await save(s=>{settings(s).interruptPackages=[...new Set(f.getAll('packages'))];return s;});closeModal();toast('专注App约定已保存');}});}
 function notifications(){requireNative();const st=nativePhoneStatus();openModal('应用外计时通知',`<p>当前活动与经过时间会显示在系统通知中，展开后可以切换活动或停止计时。它是系统通知；是否显示为顶部胶囊由设备和厂商条件决定。</p><button type="button" class="secondary" data-action="request-notifications">${st.notificationsAllowed?'查看通知权限':'允许通知'}</button><p class="quiet-note">关闭通知不删除记录。手机使用采集期间仍需显示系统运行通知。</p>`,{submit:'启用计时通知',onSubmit:async()=>{if(!nativePhoneStatus().notificationsAllowed)throw new Error('请先允许通知');await save(s=>{settings(s).notifications=true;return s;});const error=bridge().enableRuntime(!!getState().settings.phone.enabled,true);if(error)throw new Error(error);closeModal();toast('计时通知已启用');await refresh();}});}
 function editSpan(id){const state=getState(),original=state.phone.spans.find(r=>r.id===id);if(!original)return;openModal('更正手机使用时段',`<p>${e(original.label)} · ${e(original.packageName)}</p><div class="form-row"><label>开始<input type="datetime-local" name="start" step="1" value="${D.localInput(original.start,state.timeZone,true)}" required></label><label>结束<input type="datetime-local" name="end" step="1" value="${D.localInput(original.end,state.timeZone,true)}" required></label></div><label class="check"><input type="checkbox" name="remove">这整段是误记，移除</label><p class="quiet-note">只改手机使用维度。若专注主活动也被误切，请再用“整理范围”更正主时间；不会另外增加或扣减成长分。</p>`,{onSubmit:async(f,op)=>{const start=D.parseEditedLocal(f.get('start'),original.start,state.timeZone),end=D.parseEditedLocal(f.get('end'),original.end,state.timeZone);if(!f.has('remove')&&(end<=start||end>Date.now()))throw new Error('请填写已经发生、先后正确的时间');await save(s=>{const index=s.phone.spans.findIndex(r=>r.id===id);if(index<0||JSON.stringify(s.phone.spans[index])!==JSON.stringify(original))throw new Error('这条记录已变化，请重新核对');return correctPhoneSpan(s,id,{start,end,remove:f.has('remove')});},{operationId:op});closeModal();toast('手机使用时段已更正');}});}
 return {
  'refresh-phone-history':async()=>{requireNative();await save(s=>requestPhoneHistory(s));toast('已请求回补，系统可读的时段将自动更新');},
  'rebuild-phone-history':()=>{requireNative();openModal('重建今天的旧版手机记录', '<p>旧版记录和空白默认保留。重建会用系统仍可读取的时段替换今天的旧版保留区，可能覆盖旧版手动更正、恢复你曾删除的时段。</p><p>会保留一份重建前手机记录供恢复；不会改动主活动、成长、图文和新版手动更正。</p>', {submit:'保存恢复点并重建',onSubmit:async()=>{await save(s=>requestPhoneHistory(s,true));closeModal();toast('已保存手机记录恢复点并请求重建');}});},
  'undo-phone-history':()=>{openModal('恢复重建前手机记录','<p>只恢复这次重建前保存的手机时段，之后的新时段与主活动不受影响。</p>',{submit:'恢复手机记录',onSubmit:async()=>{await save(s=>undoPhoneRebuild(s));closeModal();toast('重建前手机记录已恢复');}});},
  'notification-privacy':()=>{const p=getState().settings.phone?.privacy??'activity';openModal('锁屏内容与预览',`<label>显示内容<select name="privacy">${[['summary','仅显示正在记录'],['activity','显示活动名'],['hidden','隐藏锁屏内容']].map(([v,t])=>`<option value="${v}" ${v===p?'selected':''}>${t}</option>`).join('')}</select></label><div class="preview-box" data-privacy-preview></div><p class="quiet-note">这是内容示意。系统权限、通道和锁屏设置会影响实际显示。</p>`,{onSubmit:async f=>{await save(s=>{settings(s).privacy=f.get('privacy');return s;});closeModal();}});const select=document.querySelector('#modal-form [name=privacy]'),preview=document.querySelector('[data-privacy-preview]');const update=()=>{preview.textContent=select.value==='hidden'?'锁屏不展示这条通知':select.value==='summary'?'正在记录 · 点击查看当前计时':(getState().running?getState().running.name+(getState().running.temporaryName?' · '+getState().running.temporaryName:''):'活动名称')+' · 计时中';};select.onchange=update;update();},
  'enable-phone':enable,'phone-app-rules':appRules,'enable-notifications':notifications,'edit-phone-span':editSpan,
  'request-usage':()=>{requireNative();bridge().openUsageSettings();},'timer-channel-settings':()=>{requireNative();if(!bridge().openTimerNotificationSettings)throw Error('当前安装版本不提供通道入口，请从系统应用设置打开');bridge().openTimerNotificationSettings();},
  'request-notifications':()=>{requireNative();bridge().requestNotificationPermission();},
  'disable-phone':async()=>{await save(s=>stopPhone(s));const error=bridge().enableRuntime(false,!!getState().settings.phone.notifications);if(error)toast(error);else toast('手机使用采集已关闭，已存记录保留');await refresh();},
  'disable-notifications':async()=>{if(getState().settings.phone?.enabled)throw new Error('采集期间需要系统运行通知。请先关闭手机使用记录，再关闭通知');await save(s=>{settings(s).notifications=false;return s;});bridge().disableRuntime();toast('计时通知已关闭');await refresh();},
  'toggle-live-updates':async()=>{requireNative();await save(s=>{const p=settings(s);p.liveUpdates=!p.liveUpdates;return s;});toast('已保存请求；实际提升状态请查看系统返回结果');},
  'current-phone-mode':()=>{const state=getState(),id=state.running?.id;if(!id)return;openModal('这段活动的手机约定',`<label>处理方式<select name="mode"><option value="parallel" ${state.running.phoneMode!=='focus'?'selected':''}>并行：主活动继续，只记录手机使用</option><option value="focus" ${state.running.phoneMode==='focus'?'selected':''}>专注：选中的App会切换主活动，锁屏后恢复</option></select></label><p>这次只影响当前活动。已选择 ${state.settings.phone?.interruptPackages?.length??0} 个切换App；未选择的App不打断主活动。</p>`,{onSubmit:async f=>{await save(s=>{if(s.running?.id!==id)throw new Error('当前活动已切换，请重新核对');s.running.phoneMode=f.get('mode');if(s.phone)s.phone.automation=null;return s;});closeModal();toast('当前手机约定已更新');}});}
 };
}
